    "audioKind": "soundcloud",
    "audioUrl": "https://soundcloud.com/bbvkfjik5hjo/00229-the-legend-of-hou-yi-and-chang-e-lv6-hong-kong-urban-female",
    "sourceUrl": "https://hambaanglaang.hk/00229-2/",
    "textDocumentUrl": "https://docs.google.com/document/d/1A1CWKVf6inlLjVRd9UV99j-PGZc69hE2Ad3sD3Lt9ME/edit?usp=sharing",
